"""Home reference composition; reuse existing trip, navigation and map contracts."""
def header(nav,g):
 a,icon=g['a'],g['icon']
 utility='<div class="home-utility wrap"><span>Четыре адреса. Ваша Москва.</span><div>'+a('search',icon('search')+'Поиск')+a('help',icon('headset')+'Помощь')+a('manage',icon('calendar')+'Моя бронь')+'<a class="header-phone" href="tel:88005054455">'+icon('phone')+'8 800 505 44 55</a><button class="demo-badge" data-demo-info>ДЕМО</button></div></div>'
 return '<a class="skip" href="#main">Перейти к содержанию</a><header class="header home-header">'+utility+'<div class="wrap header-inner"><div class="brand-block">'+a('home','TURRIS<span>ONLINE</span><i></i>','logo','aria-label="Туррис — главная"')+'</div><div class="nav-shell"><nav class="nav" id="main-nav" aria-label="Основное меню">'+nav+'</nav></div>'+a('booking','Выбрать номер '+icon('arrow'),'btn secondary header-booking')+'<button class="menu-button" aria-label="Открыть меню" aria-expanded="false" aria-controls="main-nav">'+icon('menu')+'<span>Меню</span></button></div></header>'

def render(p,g):
 a,image,icon,url,ext=[g[k] for k in ['a','image','icon','url','ext']]
 hotels=g['HOTELS']
 def form(bottom=False):
  s=g['booking_form'](bottom=bottom)
  for label,ic in [('Отель','pin'),('Даты поездки','calendar'),('Гости','guest')]:
   s=s.replace('>'+label+'<', '><span class="home-field-icon">'+icon(ic)+'</span><span class="home-field-label">'+('Заезд — Выезд' if label=='Даты поездки' else label)+'</span><')
  return s
 hero='<section class="hero home-hero"><div class="hero-copy"><div class="eyebrow">Четыре отеля · Москва</div><h1>Отели Туррис<br><em>в центре Москвы</em></h1><p class="sub">Четыре адреса для отдыха и деловых поездок.<br>Выберите расположение и номер на ваши даты.</p></div><figure class="hero-visual home-hero-photo">'+image('tverskaya_room_4','Тверская · стандарт с двуспальной кроватью',eager=True,sizes='(max-width:640px) 358px, (max-width:1000px) 46vw, 570px')+'<figcaption>Тверская · Номер с двуспальной кроватью</figcaption></figure><a class="text-link home-compare" href="#hotels">Сравнить отели ↓</a><div class="home-booking"><div class="eyebrow">Бронирование на сайте</div><h2>Найдите номер<br>на ваши даты</h2><p class="home-booking-intro">Выберите отель, даты и гостей.</p>'+form()+'<p class="home-rate-note">'+icon('document')+'Стоимость, питание и отмена — в выбранном тарифе.</p><div class="home-booking-help"><span>Нужна помощь с выбором?</span><a href="tel:88005054455">'+icon('phone')+'8 800 505 44 55</a></div></div><div class="hero-map-slot" data-hero-map-slot></div></section>'
 cards=''
 for i,h in hotels.items():
  tag={'tverskaya':'Семейный люкс','lubyansky':'Категории с диваном','petrovsky':'Проживание от 21 дня'}.get(i)
  cards+='<article class="hotel-card" data-hotel-card="'+i+'"><a class="photo" href="'+url(i)+'">'+image(i,'Фасад отеля '+h['full'],sizes='(max-width:640px) calc(100vw - 32px), 570px')+('<span class="home-card-tag">'+tag+'</span>' if tag else '')+'</a><div class="hotel-card-body"><h3>'+a(i,h['name'])+'</h3>'+('<span class="home-card-warning">В отеле нет лифта</span>' if i=='tagansky' else '')+'<p class="hotel-location">'+icon('pin')+h['location']+'</p><p class="address">'+h['address']+'</p><div class="home-card-actions">'+a(i+'_rooms','Номера и цены '+icon('arrow'),'btn secondary')+'<a href="#map" class="card-map-link" data-show-hotel-map="'+i+'">'+icon('pin')+'На карте</a>'+a(i,'Об отеле ↗','text-link')+'</div></div></article>'
 toolbar='<div class="explorer-toolbar"><div class="view-switch" role="group" aria-label="Способ выбора отеля"><button type="button" data-hotel-view="cards" aria-pressed="true">Карточки отелей</button><button type="button" data-hotel-view="map" aria-pressed="false">'+icon('pin')+'На карте</button></div><a class="hero-map-return text-link" href="#map">К карте отелей ↑</a>'+a('hotels','Сравнить условия ↗','text-link','data-compare-hotels')+'</div>'
 explorer='<section class="section home-explorer" id="hotels" data-hotel-explorer data-home-explorer><div class="home-explorer-head"><div class="section-heading"><div><h2>Выберите свою Москву</h2><p class="sub">Четыре отеля — четыре удобных расположения.</p></div></div>'+toolbar+'</div><div data-explorer-panel="cards"><div class="hotels-grid">'+cards+'</div><p class="selection-note">Питание и парковка зависят от отеля и тарифа.</p></div><section class="home-map-section" data-explorer-panel="map"><div class="section-heading"><div><h2>Найдите свой адрес в Москве</h2><p class="sub">Выберите отель ближе к вашим планам.</p></div><a href="#hotels" class="text-link">К карточкам ↑</a></div><div class="home-map-body">'+g['maplinks']()+'</div></section></section>'
 direct='<section class="section home-direct"><h2>Бронируйте напрямую</h2>'+g['benefits']()+'<div class="center-link">'+a('loyalty','Программа «Туррис-Бонус» '+icon('arrow'),'text-link')+'</div></section>'
 offers='<div class="home-offers"><section class="section-sm"><div class="feature"><div class="feature-media">'+image('tverskaya_room_1','Гостиная семейного люкса Тверской',sizes='(max-width:640px) calc(100vw - 32px), 350px')+'</div><div class="feature-copy"><div class="eyebrow">Тверская · семейный люкс</div><h2>Вместе — и с местом<br>для каждого</h2><p>Спальня с большой кроватью и гостиная с диваном.<br>Вместимость до 4 мест.</p>'+a('tverskaya_room_1','Посмотреть семейный люкс '+icon('arrow'),'btn secondary')+a('family','Все варианты для семьи '+icon('arrow'),'text-link')+'</div></div></section><section class="section-sm"><div class="feature pale"><div class="feature-media">'+image('petrovsky','Фасад отеля Туррис Петровский',sizes='400px')+'</div><div class="feature-copy"><div class="eyebrow">Петровский · от 21 дня</div><h2>Останьтесь в Москве подольше</h2><p>Для проектной работы или переезда.</p>'+a('longstay','Узнать условия '+icon('arrow'),'btn secondary')+'</div></div></section></div>'
 review='<section class="home-review"><h2>Гости о своём проживании</h2><div class="quote"><div class="quote-mark" aria-hidden="true">“</div><div><blockquote><p>В номере чисто, всё необходимое есть. Персонал внимательный и вежливый.</p></blockquote><span class="small">Татьяна Н. · Тверская · фрагмент отзыва на Путёвка.ком</span></div>'+ext('https://www.putevka.com/moskva/moskva/turris-tverskaya','Читать полный отзыв')+'</div></section>'
 team='<section class="team-band home-team">'+icon('guest')+'<div><h2>Разместим вашу команду</h2><p>Для компаний и организаторов групп. Подберём варианты на ваши даты и количество гостей.</p></div><div class="team-action">'+a('groups','Запросить расчёт '+icon('arrow'),'btn white')+a('business','Условия для компаний ↗','text-link')+'</div></section>'
 faq='<section class="section home-faq"><div><h2>Перед<br>бронированием</h2><p>Ответим на вопросы о вашей поездке.</p><a href="tel:88005054455">'+icon('phone')+'8 800 505 44 55</a></div>'+g['faqs'](opened=False)+'</section>'
 bottom='<section class="booking-bottom"><h2>Ваша поездка начинается с дат</h2><p class="sub">Выберите расположение и посмотрите номера на время поездки.</p>'+form(True)+'<p class="help-line">Поможем с выбором. <a href="tel:88005054455">8 800 505 44 55</a></p></section>'
 return '<div class="wrap home-page">'+hero+explorer+direct+offers+review+team+faq+bottom+'</div>'
